-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Qualitative factors in misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redstone Energy Corp., the engagement team identifies a $12,000 uncorrected misstatement that understates officers'' compensation disclosures. Overall materiality is set at $200,000. Because the misstatement affects executive compensation — a sensitive disclosure — what is the most likely effect on the auditor''s evaluation?', '["The qualitative nature may cause the auditor to conclude the misstatement is material despite being below the quantitative threshold", "The misstatement is immaterial because it falls well below the $200,000 materiality threshold regardless of its nature", "The auditor must issue a qualified opinion whenever a disclosure misstatement involves executive compensation", "The misstatement should be reclassified as a projected misstatement and extrapolated to the full population"]'::jsonb, 0, 'Under AU-C 450.11, the auditor evaluates uncorrected misstatements considering both quantitative and qualitative factors. A misstatement affecting sensitive disclosures like executive compensation may be material even below the quantitative threshold because it could influence user decisions. Choice B is incorrect because AU-C 450 explicitly requires consideration of qualitative factors — a misstatement''s nature can render it material regardless of its size relative to the numerical threshold.', 'medium', 3),

-- Q2: medium / L2 — Clearly trivial threshold for accumulation
(1, 'Misstatements and Control Deficiencies', 'While auditing Pinnacle Logistics Inc., the engagement team sets overall materiality at $150,000 and performance materiality at $112,500. The team identifies a $350 error in office supply expense classification. Under AU-C 450, how should the auditor treat this misstatement?', '["Accumulate the misstatement on the summary of uncorrected misstatements for evaluation with all other errors", "Designate the misstatement as clearly trivial and exclude it from the accumulation of identified misstatements", "Project the misstatement to the full population of operating expenses and reassess materiality", "Report the misstatement as a control deficiency to those charged with governance"]'::jsonb, 1, 'Under AU-C 450.05, the auditor may designate an amount below which misstatements are clearly trivial and need not be accumulated. A $350 error against $150,000 materiality is well below any reasonable threshold. Choice A is incorrect because AU-C 450 specifically permits the auditor to exclude clearly trivial amounts from the accumulation process, reducing unnecessary documentation for inconsequential items.', 'medium', 2),

-- Q3: medium / L2 — Tolerable misstatement in audit sampling
(1, 'Misstatements and Control Deficiencies', 'Birchwood Retail Group''s auditor sets performance materiality at $75,000 for the current-year engagement. When designing a substantive sampling test for accounts receivable, the auditor sets tolerable misstatement at $60,000. Under AU-C 530, tolerable misstatement in this context represents:', '["The maximum aggregate misstatement the auditor will accept without modifying the audit opinion", "The threshold below which individual misstatements are considered clearly trivial", "The application of performance materiality to a particular sampling procedure", "The expected misstatement the auditor anticipates based on prior-year results"]'::jsonb, 2, 'Under AU-C 530.05, tolerable misstatement is the application of performance materiality to a particular sampling procedure, representing the maximum misstatement in a population the auditor will accept for a specific test. Choice A is incorrect because it describes overall materiality for the financial statements as a whole, not the sampling-specific concept of tolerable misstatement applied to an individual account or class of transactions.', 'medium', 2),

-- Q4: hard / L4 — Evaluating aggregate near materiality with covenant pressure
(1, 'Misstatements and Control Deficiencies', 'Sterling Medical Systems'' auditor sets overall materiality at $500,000 and accumulates $465,000 in uncorrected misstatements, including a $180,000 judgmental difference in the allowance for contractual adjustments and a $285,000 projected misstatement from revenue testing. Management declines to adjust, citing immateriality. The auditor notes all misstatements increase net income and bring the entity closer to a debt covenant threshold. What is the best course of action?', '["Accept management''s position because the aggregate misstatements do not exceed the $500,000 quantitative materiality threshold", "Withdraw from the engagement because management''s refusal to correct the misstatements indicates a lack of integrity", "Require management to correct only the projected misstatement because judgmental differences are inherently subjective", "Evaluate whether proximity to the covenant threshold and the income-increasing direction make the aggregate qualitatively material and consider a qualified opinion"]'::jsonb, 3, 'Under AU-C 450.11 and AU-C 705, the auditor must evaluate both quantitative and qualitative factors when assessing uncorrected misstatements. At $465,000 against $500,000 materiality, the income-increasing bias combined with debt covenant proximity may render the misstatements qualitatively material, warranting opinion modification. Choice A is incorrect because the auditor cannot rely solely on the quantitative threshold when significant qualitative factors indicate the misstatements could influence users'' economic decisions.', 'hard', 4),

-- Q5: medium / L2 — Carryover effect of prior-year uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Granite Falls Distribution, the auditor notes that $45,000 in prior-year uncorrected misstatements related to understated prepaid insurance affect the current year''s opening balances. Current-year materiality is $180,000. Under AU-C 450, the auditor should:', '["Evaluate the effect of the prior-year uncorrected misstatements on the current year''s financial statements", "Disregard the prior-year misstatements because they were already evaluated during the prior audit engagement", "Require management to restate the prior-year comparative financial statements before continuing fieldwork", "Add the prior-year misstatement amounts to the current year''s clearly trivial threshold"]'::jsonb, 0, 'Under AU-C 450.06, the auditor must evaluate whether uncorrected misstatements from prior periods affect the current period''s financial statements. A prior-year prepaid insurance understatement reverses into the current year, affecting insurance expense recognition. Choice B is incorrect because AU-C 450 explicitly requires the auditor to consider the carryover effect of prior-year uncorrected misstatements on the current period rather than treating them as fully resolved.', 'medium', 2),

-- Q6: easy / L1 — Definition of a control deficiency
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, a control deficiency exists when:', '["The auditor identifies a material misstatement that management failed to detect before issuing financial statements", "A control is designed, implemented, or operated such that it cannot prevent or detect misstatements on a timely basis", "Management fails to file financial statements with the appropriate regulatory agency by the required deadline", "The entity experiences a financial loss exceeding the performance materiality threshold set by the auditor"]'::jsonb, 1, 'Under AU-C 265.07, a control deficiency exists when the design or operation of a control does not allow management or employees, in the normal course of performing their assigned functions, to prevent or detect and correct misstatements on a timely basis. Choice A is incorrect because a material misstatement does not automatically constitute a control deficiency — the deficiency relates to the control''s design or operation, not the misstatement''s existence alone.', 'easy', 1),

-- Q7: hard / L4 — IT access control severity classification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cascade Payment Solutions, the auditor discovers that three programmers have unrestricted access to modify production financial reporting applications without a change management review. The programmers processed 8,200 changes during the year. No unauthorized modifications were identified through quarterly reconciliation procedures, but the lack of preventive controls means any programmer could alter financial calculations undetected until quarter-end. The auditor should classify this deficiency as:', '["An inconsequential deficiency because no actual unauthorized changes were detected during testing", "A control deficiency that does not require communication because detective controls compensate adequately", "A significant deficiency because the quarterly detective procedures reduce the likelihood of material misstatement", "A material weakness because the absence of preventive change management controls creates a reasonable possibility that a material misstatement would not be prevented or detected on a timely basis"]'::jsonb, 3, 'Under AU-C 265.A13, the auditor evaluates whether there is a reasonable possibility that the deficiency could result in a material misstatement not being prevented or detected timely. Unrestricted production access without preventive review is a material weakness because quarter-end detection leaves a significant window for undetected material misstatements. Choice C is incorrect because the delayed nature of quarterly reconciliation does not adequately compensate for the missing preventive control over production financial application changes.', 'hard', 4),

-- Q8: medium / L3 — Cascading effect of unrecorded accrual
(1, 'Misstatements and Control Deficiencies', 'Maplewood Construction Corp. failed to accrue $95,000 in subcontractor expenses at December 31, 2025. The auditor is analyzing how this single misstatement affects the financial statements as a whole. What is the most likely effect of this unrecorded accrual?', '["Net income and total liabilities are both understated, while retained earnings is overstated", "Net income is overstated, total assets are understated, and stockholders'' equity is correctly stated", "Net income and retained earnings are overstated, total liabilities are understated, and total equity is overstated by $95,000", "Net income is overstated and total liabilities are understated, but total assets remain correctly stated"]'::jsonb, 2, 'Under AU-C 450, the auditor evaluates misstatements'' effects on financial statements as a whole. A missing expense accrual understates expenses (overstating net income and retained earnings by $95,000), understates accrued liabilities, and overstates total equity. Total assets are unaffected because cash has not been disbursed. Choice D is incorrect because while it correctly identifies the income and liability effects, it omits the overstatement of total equity that results from overstated retained earnings flowing into stockholders'' equity.', 'medium', 3),

-- Q9: medium / L3 — Direction of misstatements indicating management bias
(1, 'Misstatements and Control Deficiencies', 'While auditing Lakeshore Pharmaceuticals, the engagement team accumulates eight uncorrected misstatements totaling $78,000 against materiality of $250,000. All eight misstatements increase reported net income — six overstate revenue and two understate expenses. What is the most likely implication the auditor should consider?', '["The misstatements are immaterial at 31% of overall materiality and require no further evaluation", "The auditor should project each misstatement to the full population to determine the total likely error amount", "Each misstatement should be evaluated individually rather than in aggregate because they affect different line items", "The consistent income-increasing direction may indicate management bias, requiring the auditor to reassess fraud risk"]'::jsonb, 3, 'Under AU-C 450.A18, the auditor considers whether uncorrected misstatements share a common characteristic — such as all increasing income — that could indicate management bias. A pattern of uniformly income-increasing errors suggests potential intentional manipulation rather than random errors. Choice A is incorrect because AU-C 240 and AU-C 450 require the auditor to evaluate the directional pattern of misstatements as a potential fraud risk indicator regardless of whether the aggregate falls below quantitative materiality.', 'medium', 3),

-- Q10: easy / L1 — Deficiency in design definition
(1, 'Misstatements and Control Deficiencies', 'A deficiency in the design of an internal control exists when:', '["A necessary control is missing or not properly structured to meet its objective even if it operates as designed", "A properly designed control is not applied consistently by employees responsible for performing it", "The auditor determines that a control has been intentionally overridden by a member of senior management", "The entity fails to correct a previously communicated significant deficiency within one fiscal year"]'::jsonb, 0, 'Under AU-C 265.A7, a deficiency in design exists when a control necessary to meet a control objective is missing or not properly designed so that even if it operates as intended, the objective would not be met. Choice B is incorrect because it describes a deficiency in operation — where a properly designed control fails to operate effectively — rather than a fundamental flaw in the control''s underlying design itself.', 'easy', 1),

-- Q11: hard / L4 — Must communicate deficiency even if management already knows
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cedarbrook Holdings, the auditor identifies a significant deficiency in revenue recognition that management disclosed to the audit committee six months ago. Management asserts remediation is in progress but will not be complete until next quarter. The engagement partner questions whether written communication is required given management''s prior awareness. The auditor should:', '["Omit the deficiency from the written communication because management already informed the audit committee and remediation is underway", "Include the deficiency in the written communication to those charged with governance regardless of management''s prior disclosure", "Defer the written communication until the next quarter when remediation is expected to be complete", "Communicate the deficiency only verbally to the audit committee and document the oral exchange in workpapers"]'::jsonb, 1, 'Under AU-C 265.13, the auditor is required to communicate significant deficiencies and material weaknesses in writing to those charged with governance regardless of whether management has previously informed them. The auditor''s independent written assessment serves a distinct purpose from management''s disclosure. Choice A is incorrect because AU-C 265 does not provide an exemption from the written communication requirement merely because management previously disclosed the deficiency to the audit committee.', 'hard', 4),

-- Q12: easy / L1 — Written communication timing
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, the auditor''s written communication of significant deficiencies and material weaknesses to those charged with governance should be made no later than:', '["Five business days after identifying each individual deficiency during fieldwork", "The date the auditor''s report on the financial statements is issued", "60 days following the report release date", "The beginning of the subsequent audit engagement"]'::jsonb, 2, 'Under AU-C 265.13, the auditor should communicate significant deficiencies and material weaknesses in writing no later than 60 days following the report release date. This timeline allows the auditor to complete the full evaluation before formalizing the communication. Choice B is incorrect because AU-C 265 permits the written communication to be made after the auditor''s report is issued, provided it falls within the 60-day window following the report release date.', 'easy', 1),

-- Q13: easy / L1 — Clearly trivial definition
(1, 'Misstatements and Control Deficiencies', 'In the context of evaluating audit misstatements, the term ''clearly trivial'' under AU-C 450 means the misstatement is:', '["Below performance materiality but above the tolerable misstatement threshold for the account tested", "Caused by an unintentional error rather than a fraudulent act committed by management or employees", "Corrected by management before the completion of audit fieldwork procedures", "So inconsequential that it would not need to be accumulated with other identified misstatements"]'::jsonb, 3, 'Under AU-C 450.A2, clearly trivial describes matters that are inconsequential whether taken individually or in the aggregate, and whether judged by size, nature, or circumstances. Misstatements below this threshold need not be accumulated. Choice A is incorrect because clearly trivial is a much lower threshold than performance materiality — it addresses items so small they are beneath consideration, not items merely below a calculated audit benchmark.', 'easy', 1),

-- Q14: easy / L1 — Management representation letter regarding uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 580, the management representation letter regarding uncorrected misstatements must include a statement that management:', '["Has corrected all misstatements identified by the auditor during the audit engagement", "Believes the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole", "Accepts full legal liability for any uncorrected misstatements remaining in the issued financial statements", "Has disclosed all uncorrected misstatements to the entity''s external legal counsel for review"]'::jsonb, 1, 'Under AU-C 580.A5 and AU-C 450.14, the auditor requests a written representation that management believes the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole. A summary of such items is included with the letter. Choice A is incorrect because the representation addresses management''s assessment of uncorrected misstatements'' immateriality, not a claim that all identified misstatements have been corrected.', 'easy', 1),

-- Q15: medium / L2 — Missing reconciliation classified as operating deficiency
(1, 'Misstatements and Control Deficiencies', 'At Brookfield Manufacturing, company policy requires the controller to reconcile the general ledger inventory account to the perpetual inventory subsidiary ledger monthly. During the audit, the engagement team finds that reconciliations were not performed for August, September, and October 2025. Under AU-C 265, this situation represents:', '["A deficiency in design because the control was not properly structured to address the inventory reconciliation objective", "A material weakness because three consecutive months of missed reconciliations will inevitably produce undetected misstatements", "A deficiency in operation because the properly designed control was not consistently performed as intended", "An entity-level control failure that must be reported immediately to regulatory authorities"]'::jsonb, 2, 'Under AU-C 265.A7, a deficiency in operation exists when a properly designed control does not operate effectively. The monthly reconciliation policy is properly designed, but the controller failed to perform it for three consecutive months. Choice A is incorrect because the control design is sound — the company policy requiring monthly reconciliation exists — but the controller failed to execute it consistently, making this an operational deficiency rather than a design flaw.', 'medium', 2),

-- Q16: medium / L2 — Depreciation error classified as factual misstatement
(1, 'Misstatements and Control Deficiencies', 'Valleyview Equipment Leasing recorded $340,000 in depreciation expense for delivery trucks using a 3-year useful life. The auditor determines the trucks have a 5-year useful life supported by manufacturer specifications and industry data, making correct depreciation $204,000. Under AU-C 450, this $136,000 overstatement is classified as:', '["A projected misstatement because the error was identified through analytical procedures applied to the fleet", "A judgmental misstatement because it involves an accounting estimate about the assets'' useful life", "An unrecorded adjustment that should be deferred and evaluated only in the subsequent audit period", "A factual misstatement because the useful life is supported by objective evidence and is not subject to reasonable disagreement"]'::jsonb, 3, 'Under AU-C 450.A3, a factual misstatement is one about which there is no doubt. When useful life is established by manufacturer specifications and objective industry data rather than subjective judgment, the resulting depreciation error is factual. Choice B is incorrect because a judgmental misstatement arises from differences in management''s judgment about estimates where reasonable minds could differ — here the useful life is objectively determinable, not an exercise of professional judgment.', 'medium', 2),

-- Q17: medium / L2 — Projected misstatement calculation from sample
(1, 'Misstatements and Control Deficiencies', 'While auditing Northshore Distributors, the auditor selects a random sample of 40 invoices from a population of 3,200 invoices and identifies pricing errors totaling $2,400 in the sample. Under AU-C 530, the projected misstatement for the population using ratio estimation is:', '["$192,000, calculated by applying the per-item error rate to the total population count", "$2,400, limited to the actual errors identified in the tested sample items", "$76,800, calculated by applying the error percentage only to the 3,160 untested items", "$96,000, calculated by averaging the sample errors and multiplying by half the population"]'::jsonb, 0, 'Under AU-C 530.A23, the auditor projects the misstatement found in a sample to the population. The average error per item is $2,400 divided by 40 items, or $60 per item, multiplied by the population of 3,200 invoices, yielding a projected misstatement of $192,000. Choice B is incorrect because AU-C 530 requires the auditor to project sample errors to the entire population rather than limiting the estimated misstatement to only errors actually found in tested items.', 'medium', 2),

-- Q18: easy / L1 — Preventive vs detective controls
(1, 'Misstatements and Control Deficiencies', 'A preventive control is best described as a control that:', '["Identifies misstatements after they have occurred and initiates corrective action promptly", "Monitors the effectiveness of other controls through periodic testing and reporting", "Documents exceptions found during management''s review of monthly financial reports", "Stops errors or irregularities from occurring before a transaction is processed or recorded"]'::jsonb, 3, 'Preventive controls are designed to deter errors or irregularities from occurring in the first place — for example, segregation of duties or authorization requirements that stop improper transactions before processing. Under AU-C 315.A79, understanding the nature of controls helps the auditor evaluate deficiency severity. Choice A is incorrect because it describes a detective control, which identifies misstatements after they have already occurred rather than preventing them from happening initially.', 'easy', 1),

-- Q19: easy / L1 — Misstatements encompass both errors and fraud
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, the term ''misstatement'' in an audit context encompasses:', '["Only errors resulting from unintentional mistakes in gathering or processing financial data", "Differences between reported amounts and amounts required by the applicable financial reporting framework, whether caused by error or fraud", "Only fraud-related adjustments that the auditor identifies during substantive testing procedures", "Reclassification entries proposed by the auditor that management has agreed to record voluntarily"]'::jsonb, 1, 'Under AU-C 450.04, a misstatement is a difference between the amount, classification, presentation, or disclosure of a reported financial statement item and the amount required under the applicable framework. This definition includes both errors and fraud. Choice A is incorrect because AU-C 450 defines misstatements broadly to include both intentional (fraud) and unintentional (error) differences, not only unintentional mistakes.', 'easy', 1),

-- Q20: medium / L3 — Control environment strength effect on deficiency severity
(1, 'Misstatements and Control Deficiencies', 'Summit Ridge Manufacturing has active board oversight, a robust internal audit function, and experienced accounting staff. The auditor identifies a deficiency in the approval process for manual journal entries exceeding $50,000. What is the most likely effect of the strong control environment on the auditor''s evaluation of this deficiency?', '["The strong control environment eliminates the deficiency because other controls will prevent all potential misstatements", "The control environment strength may reduce the severity classification if entity-level monitoring controls effectively mitigate the risk of undetected errors", "The auditor must classify the deficiency as a material weakness regardless of any compensating entity-level controls", "The strong control environment requires the auditor to perform additional testing of all manual journal entries"]'::jsonb, 1, 'Under AU-C 265.A14, the auditor considers entity-level controls, including the control environment, when evaluating the severity of identified deficiencies. A strong control environment with active board oversight and internal audit may reduce the severity classification if these controls effectively mitigate the risk posed by the specific deficiency. Choice A is incorrect because a strong control environment reduces but does not eliminate the deficiency — the auditor must still evaluate the specific control gap and cannot assume other controls fully compensate.', 'medium', 3),

-- Q21: hard / L4 — Evaluating when management disagrees with material weakness classification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ridgeline Financial Corp., the auditor classifies a deficiency in the loan loss reserve estimation process as a material weakness. Management argues the deficiency is only a significant deficiency because no actual misstatement resulted during the period. The audit committee requests the auditor to reconsider the classification. The auditor should:', '["Maintain the material weakness classification if the auditor''s professional judgment supports it, regardless of management''s or the audit committee''s disagreement", "Downgrade the classification to significant deficiency because the audit committee''s request reflects those charged with governance''s informed perspective", "Accept management''s position because the absence of an actual misstatement proves the deficiency cannot rise to the level of a material weakness", "Defer the classification decision until the subsequent audit to determine whether a misstatement actually occurs"]'::jsonb, 0, 'Under AU-C 265.12, the auditor exercises independent professional judgment when evaluating the severity of identified deficiencies. The classification depends on the reasonable possibility of a material misstatement, not whether one actually occurred. Management disagreement or audit committee requests do not override the auditor''s assessment. Choice C is incorrect because AU-C 265.A12 clarifies that a material weakness can exist even if no misstatement was detected — the evaluation focuses on the potential for misstatement, not actual occurrence.', 'hard', 4),

-- Q22: hard / L3 — Analyzing entity-level control weakness impact on transaction controls
(1, 'Misstatements and Control Deficiencies', 'During the audit of Thornton Consolidated Industries, the auditor discovers that the CFO has sole authority to approve, record, and reconcile all intercompany transactions without independent review. Individual intercompany entries have been accurate, but the auditor is evaluating how this entity-level weakness in tone at the top and oversight affects the overall control environment. What is the most likely effect on the auditor''s assessment?', '["The accuracy of individual transactions demonstrates effective controls, so no deficiency exists at any level", "The lack of oversight over the CFO''s authority increases the risk that a material misstatement could occur and not be detected, likely indicating a material weakness in the entity-level control environment", "The deficiency is limited to the intercompany account and does not affect the broader control environment assessment", "The auditor should classify this only as a significant deficiency because no actual misstatement has been identified"]'::jsonb, 1, 'Under AU-C 265.A10, entity-level deficiencies — particularly those related to the control environment such as management override and lack of segregation of duties — can have a pervasive effect on the financial statements. The CFO''s unchecked authority over intercompany transactions represents a material weakness in the control environment. Choice D is incorrect because the severity classification under AU-C 265.A12 is based on the reasonable possibility of undetected material misstatement, not whether an actual misstatement has already been identified.', 'hard', 3),

-- Q23: medium / L3 — Segregation of duties weakness analysis
(1, 'Misstatements and Control Deficiencies', 'At Westfield Community Credit Union, a single employee handles both member deposit processing and the daily reconciliation of the deposit clearing account. The auditor is evaluating the potential consequences of this arrangement. What is the most likely control risk created by this lack of segregation of duties?', '["The employee may process deposits more slowly because of the dual responsibilities, causing reporting delays", "The risk that unauthorized transactions could be concealed because the same person who processes deposits also controls the reconciliation that would detect irregularities", "The arrangement increases audit fees because the auditor must perform additional substantive procedures on all deposit accounts", "The credit union will be required to restate its financial statements for the current and prior periods"]'::jsonb, 2, 'Under AU-C 315.A80, segregation of duties is a key preventive control. When one person both processes and reconciles transactions, the opportunity to conceal errors or fraud increases because the reconciliation that would normally detect irregularities is performed by the same individual. Choice A is incorrect because the primary risk from inadequate segregation of duties is concealment of misstatements, not processing delays — the control concern relates to detection capability rather than operational efficiency.', 'medium', 3),

-- Q24: easy / L2 — Applying basic misstatement accumulation
(1, 'Misstatements and Control Deficiencies', 'Elkridge Furniture Co.''s auditor has set materiality at $100,000 and the clearly trivial threshold at $2,500. During testing, the auditor identifies misstatements of $4,200, $8,500, and $1,800. Under AU-C 450, the auditor should accumulate:', '["All three misstatements because each one exceeds the clearly trivial threshold", "Only the $4,200 and $8,500 misstatements, excluding the $1,800 because it falls below the clearly trivial threshold", "Only the $8,500 misstatement because the other two are individually immaterial relative to the $100,000 materiality", "No misstatements because the combined total of $14,500 is below performance materiality"]'::jsonb, 1, 'Under AU-C 450.05, the auditor accumulates all identified misstatements except those that are clearly trivial. With a clearly trivial threshold of $2,500, the $4,200 and $8,500 misstatements must be accumulated, while the $1,800 misstatement falls below the threshold and may be excluded. Choice A is incorrect because the $1,800 misstatement is below the $2,500 clearly trivial threshold and therefore does not require accumulation under AU-C 450.', 'easy', 2),

-- Q25: medium / L2 — Determining misstatement type from sampling procedures
(1, 'Misstatements and Control Deficiencies', 'While testing accounts payable at Crestline Distribution, the auditor selects 30 disbursements from a population of 4,500 and finds that two invoices totaling $6,300 were recorded in the wrong accounting period. The auditor has verified that the $6,300 is the exact amount of the cutoff errors in the sample. Under AU-C 450, the $6,300 should be classified as:', '["A judgmental misstatement because cutoff determinations require professional judgment about the correct period", "A clearly trivial misstatement because $6,300 is well below the overall materiality for the engagement", "A known misstatement for the sample that must be projected to the untested population to estimate the total likely misstatement", "A factual misstatement that should be recorded as an audit adjustment without any further projection"]'::jsonb, 2, 'Under AU-C 450.A4 and AU-C 530.A23, misstatements found in a sample are known amounts within the sample but must be projected to the population to estimate the total misstatement. The $6,300 cutoff error represents the known misstatement in the sample, requiring projection to the 4,500-item population. Choice D is incorrect because when misstatements are found through sampling, AU-C 530 requires the auditor to project the sample results to the population rather than treating the sample errors as the total misstatement.', 'medium', 2),

-- Q26: medium / L2 — Communication of deficiencies below significant deficiency level
(1, 'Misstatements and Control Deficiencies', 'During the audit of Harborview Marine Services, the auditor identifies several control deficiencies that individually and in combination do not rise to the level of a significant deficiency. The auditor has already communicated significant deficiencies and material weaknesses in writing. Under AU-C 265, the auditor''s obligation regarding these lesser deficiencies is:', '["The auditor must include all identified deficiencies in the written communication to those charged with governance", "The auditor is prohibited from communicating deficiencies that are less severe than significant deficiencies", "The auditor may communicate these deficiencies to management or those charged with governance but is not required to do so", "The auditor must communicate these deficiencies to an external regulatory body for public disclosure"]'::jsonb, 2, 'Under AU-C 265.A19, the auditor may communicate control deficiencies that are not significant deficiencies to management, particularly if the deficiencies could be improved upon, but is not required to do so. The required written communication covers only significant deficiencies and material weaknesses. Choice B is incorrect because AU-C 265 does not prohibit communicating lesser deficiencies — it simply does not require their communication, leaving it to the auditor''s judgment whether the information would benefit management.', 'medium', 2),

-- Q27: medium / L3 — Effect of accounting staff turnover on deficiency evaluation
(1, 'Misstatements and Control Deficiencies', 'Clearwater Electronics experienced 80% turnover in its accounting department during the year, replacing four of five staff members. The new employees have limited experience with the company''s accounting software and policies. The auditor is evaluating how this staffing change affects the control environment. What is the most likely effect on the auditor''s risk assessment?', '["The high turnover increases the risk of control deficiencies in operation because inexperienced staff may not perform established controls effectively, warranting expanded substantive testing", "The turnover has no effect on the control environment because the accounting policies and procedures remain unchanged", "The auditor should withdraw from the engagement because high accounting turnover indicates potential fraud", "The turnover requires the auditor to redesign the control testing plan to rely solely on inquiry of new personnel"]'::jsonb, 0, 'Under AU-C 315.A73, the auditor considers the competence of personnel when evaluating the control environment. High turnover with inexperienced replacements increases the risk that properly designed controls may not operate effectively, requiring the auditor to expand substantive procedures. Choice B is incorrect because AU-C 315 recognizes that controls depend on the people who execute them — unchanged policies are insufficient if the staff performing those controls lack the competence to apply them correctly.', 'medium', 3),

-- Q28: easy / L1 — Auditor not required to search for deficiencies
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, the auditor''s responsibility regarding internal control deficiencies during a financial statement audit is to:', '["Perform a comprehensive search for all possible deficiencies in every area of internal control", "Communicate to those charged with governance any significant deficiencies or material weaknesses identified during the audit", "Provide assurance that no significant deficiencies or material weaknesses exist in the entity''s internal controls", "Test every internal control that operates during the period covered by the financial statements"]'::jsonb, 1, 'Under AU-C 265.11, the auditor communicates significant deficiencies and material weaknesses identified during the audit. The auditor is not required to perform procedures specifically designed to identify all deficiencies or to express an opinion on the effectiveness of internal control in a financial statement audit. Choice A is incorrect because AU-C 265 requires communication of deficiencies identified during the audit, not a comprehensive search — the auditor''s procedures are designed to support the opinion on the financial statements, not to identify every possible control deficiency.', 'easy', 1),

-- Q29: medium / L3 — Net vs gross evaluation of offsetting misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ridgemont Aerospace, the engagement team finds that revenue is overstated by $120,000 due to a cutoff error and cost of goods sold is understated by $85,000 due to an inventory costing error. Both misstatements increase net income. Materiality is $200,000. What is the most likely approach the auditor should take when evaluating these misstatements?', '["Net the two misstatements to $35,000 and conclude they are immaterial because the offset reduces the aggregate effect", "Consider only the $120,000 revenue misstatement because revenue is the more significant line item for users", "Evaluate the misstatements both individually by account and in the aggregate as a $205,000 combined effect on net income", "Disregard both misstatements because neither one individually exceeds the $200,000 materiality threshold"]'::jsonb, 2, 'Under AU-C 450.11, the auditor evaluates uncorrected misstatements individually and in the aggregate. Because both misstatements increase net income in the same direction, their combined effect on net income is $205,000 ($120,000 + $85,000), which exceeds the $200,000 materiality threshold. Choice A is incorrect because netting misstatements that affect different financial statement line items but move income in the same direction understates their combined effect — the auditor must consider the cumulative impact on the affected financial statement captions.', 'medium', 3),

-- Q30: hard / L4 — Evaluating series of immaterial misstatements for collective opinion impact
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Northwest Timber Corp., the engagement team identifies 23 uncorrected misstatements across revenue, inventory, and accounts payable. No single misstatement exceeds $18,000 against materiality of $400,000. However, the aggregate totals $375,000, all misstatements increase net income, and management has consistently resisted recording adjustments over the past three years. The engagement partner is evaluating the appropriate audit opinion. What is the best course of action?', '["Request management to record adjusting entries sufficient to reduce the aggregate below materiality, and if management refuses, evaluate whether a qualified opinion is warranted based on the cumulative amount, income-increasing pattern, and management''s persistent resistance to adjustments", "Issue an unmodified opinion because no individual misstatement is material and the aggregate does not exceed the $400,000 threshold", "Issue an adverse opinion because 23 misstatements indicate pervasive problems with the financial statements", "Withdraw from the engagement because management''s consistent refusal to record adjustments over three years constitutes a scope limitation"]'::jsonb, 0, 'Under AU-C 450.12 and AU-C 705, the auditor must request management to correct material misstatements. When the aggregate approaches materiality at $375,000 of $400,000, the income-increasing pattern and management''s persistent resistance are qualitative factors that may render the effect material under AU-C 450.11. If management refuses, a qualified opinion may be appropriate. Choice B is incorrect because AU-C 450 requires evaluation of both quantitative closeness to materiality and qualitative indicators like directional bias and management''s attitude toward adjustments.', 'hard', 4)
;

COMMIT;
